INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 1, 2, 3000, "vo_minigame_1013_icon_2_002_001", "調子が上がって\nきたなっ", 2, 1000, "vo_minigame_1013_icon_1_002_001", "訓練はまだ\nここからですわ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 2, 2, 3000, "vo_minigame_1013_icon_2_003_001", "ほらほら、\nまだいけるだろ？", 2, 5000, "vo_minigame_1013_icon_1_003_001", "クスクス、悪くない\n流れですわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 3, 2, 3000, "vo_minigame_1013_icon_2_004_001", "へへっ、おまえら\nやるじゃねえか！", 3, 10000, "vo_minigame_1013_icon_1_004_001", "すばらしい\n記録ですわ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 4, 2, 3000, "vo_minigame_1013_icon_2_005_001", "あたしたちはまだ\n止まらねえぜ！", 3, 10000, "vo_minigame_1013_icon_1_005_001", "乗りに乗って\nいますわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 5, 2, 3000, "vo_minigame_1013_icon_2_005_002", "見てろよ！\nマコト班の快進撃だ！", 3, 10000, "vo_minigame_1013_icon_1_005_002", "まだまだ行きます\nついてきなさい");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 6, 2, 3000, "vo_minigame_1013_icon_2_005_003", "うおぉぉっ！\n絶好調だぜ！", 3, 10000, "vo_minigame_1013_icon_1_005_003", "エリコ班の\n本領発揮ですわ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 7, 2, 3000, "vo_minigame_1013_icon_2_006_001", "どこまで行けるか\n楽しみだなっ！", 3, 0, "vo_minigame_1013_icon_1_006_001", "ここからは\n前人未到の領域です！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 8, 3, 1000, "vo_minigame_1013_icon_2_007_001", "まだ諦めんなよっ", 4, 1, "vo_minigame_1013_icon_1_007_001", "厄介でしたわ…");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 9, 3, 1000, "vo_minigame_1013_icon_2_007_002", "冷やっとしたぜ…！", 4, 1, "vo_minigame_1013_icon_1_007_002", "油断大敵です");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 10, 3, 1000, "vo_minigame_1013_icon_2_007_003", "弱音を吐くなっ", 4, 1, "vo_minigame_1013_icon_1_007_003", "忌々しいっ…");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 11, 4, 1500, "vo_minigame_1013_icon_2_008_001", "マコト班集合！", 3, 99, "vo_minigame_1013_icon_1_008_001", "大所帯ですわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 12, 4, 1500, "vo_minigame_1013_icon_2_008_002", "連携してくぞ！", 3, 99, "vo_minigame_1013_icon_1_008_002", "エリコ班へようこそ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (8, 13, 1, 3000, "vo_minigame_1013_icon_2_020_001", "みんなに力を！", 6, 0, "vo_minigame_1013_icon_1_020_001", "ナナカちゃんに\nお任せあれ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (9, 14, 1, 3000, "vo_minigame_1013_icon_2_022_001", "任せてくれたまえ", 7, 0, "vo_minigame_1013_icon_1_022_001", "はっはっは！\n任せろ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (10, 15, 1, 3000, "vo_minigame_1013_icon_2_023_001", "ほな、いきまひょか", 8, 0, "vo_minigame_1013_icon_1_023_001", "どんどんいくわよ");
